688|func CheckResourceVMLockIsEXP(ctx context.Context, areaType, vmid int, uid int64, flowID string) bool {
689|	logs := vlog.FromContext(ctx)
690|	// 从session中获取信息,如果session找不到就认为需要处理
691|	session := &app.ResourceVM{}
692|	flag, err := session.GetSession(areaType, uid, toolsglobal.ResouceRedisCLI)
693|	if err != nil {
694|		logs.Errorf("CheckResourceVMLockIsEXP: GetSession Failed, err[%v] areaType[%d] uid[%d], flowID[%s]", err, areaType, uid, flowID)
695|		return false
696|	}
697|	if !flag {
698|		logs.Debugf("CheckResourceVMLockIsEXP: Failed, session not found. exped, areaType[%d] uid[%d], flowID[%s]", areaType, uid, flowID)
699|		return true
700|	}
701|
702|	if session.VMID != vmid {
703|		logs.Debugf("CheckResourceVMLockIsEXP: session flowID not match, exped, areaType[%d] uid[%d], flowID[%s]", areaType, uid, flowID)
704|		return true
705|	}
706|
707|	if session.LockedFlowID != flowID {
708|		logs.Debugf("CheckResourceVMLockIsEXP: session flowID not match, exped, areaType[%d] uid[%d], flowID[%s]", areaType, uid, flowID)
709|		return true
710|	}
711|
712|	// 检查过期
713|	if time.Now().Sub(session.CreateTime).Seconds() > float64(session.ExpirationS) {
714|		return true
715|	}
716|
717|	return false
718|}
